  serviceName: string;
  serviceCode: string;
  totalCharge: Money;
  estimatedDeliveryDate?: Date;
}

export type CarrierResult<T> = 
  | { success: true; data: T }
  | { success: false; error: { code: string; message: string; rawError?: unknown } };

// /domain/ports/shipping-carrier.port.ts
export interface ShippingCarrierPort {
  readonly carrierId: 'FEDEX' | 'UPS' | 'DHL';
  getRates(request: RateRequest): Promise<CarrierResult<RateQuote[]>>;
