#### 2. Isolated Carrier Adapter & ACL Mapper (`/infrastructure/carriers/fedex/`)

```typescript
// /infrastructure/carriers/fedex/fedex.mapper.ts
// SDK imports stay confined strictly within this directory
import type { FedExRateRequestPayload, FedExRateResponsePayload } from 'fedex-sdk-types';
import type { RateRequest, RateQuote } from '../../../domain/model/shipping';

export function toFedExRatePayload(domainReq: RateRequest): FedExRateRequestPayload {
  return {
    accountNumber: { value: process.env.FEDEX_ACCOUNT_NUMBER ?? '' },
    requestedShipment: {
      shipper: {
        address: {
          streetLines: domainReq.origin.streetLines,
          city: domainReq.origin.city,
          stateOrProvinceCode: domainReq.origin.stateOrProvince,
          postalCode: domainReq.origin.postalCode,
          countryCode: domainReq.origin.countryCode,
        },
      },
      recipient: {
        address: {
          streetLines: domainReq.destination.streetLines,
          city: domainReq.destination.city,
          stateOrProvinceCode: domainReq.destination.stateOrProvince,
          postalCode: domainReq.destination.postalCode,
          countryCode: domainReq.destination.countryCode,
        },
      },
      requestedPackageLineItems: domainReq.packages.map((p) => ({
        weight: { value: p.weight, units: p.weightUnit === 'LB' ? 'LB' : 'KG' },
        dimensions: { length: p.length, width: p.width, height: p.height, units: p.unit },
      })),
    },
  };
}

export function toDomainRateQuotes(rawResponse: FedExRateResponsePayload): RateQuote[] {
  const rateDetails = rawResponse.output?.rateReplyDetails ?? [];
  return rateDetails.map((detail) => {
    const totalNetCharge = detail.ratedShipmentDetails?.[0]?.totalNetCharge ?? 0;
    const currency = detail.ratedShipmentDetails?.[0]?.currency ?? 'USD';

    return {
      carrierId: 'FEDEX',
      serviceName: detail.serviceName ?? 'FedEx Standard',
      serviceCode: detail.serviceType ?? 'FEDEX_EXPRESS',
      totalCharge: { amount: totalNetCharge, currency },
      estimatedDeliveryDate: detail.operationalDetail?.deliveryDate 
        ? new Date(detail.operationalDetail.deliveryDate) 
        : undefined,
    };
  });
}
```

```typescript
// /infrastructure/carriers/fedex/fedex.adapter.ts
import type { ShippingCarrierPort } from '../../../domain/ports/shipping-carrier.port';
import type { RateRequest, RateQuote, CarrierResult } from '../../../domain/model/shipping';
import { toFedExRatePayload, toDomainRateQuotes } from './fedex.mapper';

export class FedExAdapter implements ShippingCarrierPort {
  readonly carrierId = 'FEDEX';

  constructor(private readonly fedexClient: { getRates: (payload: unknown) => Promise<unknown> }) {}

  async getRates(request: RateRequest): Promise<CarrierResult<RateQuote[]>> {
    try {
      const payload = toFedExRatePayload(request);
      const rawResult = await this.fedexClient.getRates(payload);
      const quotes = toDomainRateQuotes(rawResult as any);
      return { success: true, data: quotes };
    } catch (err: any) {
      return {
        success: false,
        error: {
          code: 'FEDEX_RATE_ERROR',
          message: err?.message ?? 'Failed to fetch FedEx rates',
          rawError: err,
        },
      };
    }
  }
}
```

